"""Every generated file has a registered generator, and every script that writes files is accounted for.

The registry is flow_graph/param/regen_manifest.json: pipeline stages (outputs, amends, invokes) and not_stages
(scripts that write files but are not generators of repository content, each with a role and a reason).
Nothing here lists files. The tests discover them:
  * scripts that write files, found by parsing every tracked Python file;
  * files that say they are generated ("Generated by `<script>`");
  * files marked linguist-generated in .gitattributes.
Run: python3 -m pytest flow_graph/test_generators.py"""
import ast, fnmatch, json, os, re, subprocess

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
MANIFEST = json.load(open(os.path.join(ROOT, 'flow_graph', 'param', 'regen_manifest.json')))
TRACKED = [f for f in subprocess.run(['git', 'ls-files'], cwd=ROOT, capture_output=True, text=True, check=True).stdout.splitlines()
           if os.path.lexists(os.path.join(ROOT, f))]   # a file deleted in the working tree is no longer part of it
WRITE_CALLS = {'write_text', 'write_bytes', 'savefig', 'to_csv', 'to_excel', 'exportStl', 'exportStep', 'imwrite', 'save_workbook'}
EXTERNAL_TOOLS = ('openscad', 'ffmpeg', 'freecadcmd')


def match(path, globs):
    return any(fnmatch.fnmatch(path, g) for g in globs)


def stage_script(argv):
    """The repository script a stage command runs: `python3 path.py`, `python3 -m pkg.mod` or `bash path.sh`."""
    if '-m' in argv:
        mod = argv[argv.index('-m') + 1].replace('.', '/')
        return mod + '.py' if os.path.isfile(os.path.join(ROOT, mod + '.py')) else mod + '/__main__.py'
    return next((a for a in argv[1:] if a.endswith(('.py', '.sh'))), None)


STAGES = MANIFEST['stages']
RUN_GLOBS = [stage_script(s['argv']) for s in STAGES] + [g for s in STAGES for g in s.get('invokes', [])]
NOT_STAGE_GLOBS = [g for n in MANIFEST.get('not_stages', []) for g in n['scripts']]
OWNED_GLOBS = ([g for s in STAGES for g in s.get('outputs', []) + s.get('amends', [])]
               + [MANIFEST['receipt']])   # the receipt is written by regen.py itself


def writes_files(src):
    """True when the source opens a file for writing, calls a known writer, or runs an external model builder."""
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return False
    for n in ast.walk(tree):
        if not isinstance(n, ast.Call):
            continue
        f = n.func
        name = f.id if isinstance(f, ast.Name) else f.attr if isinstance(f, ast.Attribute) else ''
        if name == 'open':
            args = n.args[1:2] if isinstance(f, ast.Name) else n.args[0:1]
            mode = next((a.value for a in args if isinstance(a, ast.Constant) and isinstance(a.value, str)), None)
            mode = next((k.value.value for k in n.keywords if k.arg == 'mode' and isinstance(k.value, ast.Constant)), mode)
            if mode and any(c in mode for c in 'wax'):
                return True
        if name in WRITE_CALLS or (isinstance(f, ast.Attribute) and name in ('export', 'save', 'saveAs')):
            return True
        if name in ('run', 'call', 'check_call', 'check_output', 'Popen'):
            if any(isinstance(c, ast.Constant) and isinstance(c.value, str) and any(t in c.value for t in EXTERNAL_TOOLS)
                   for c in ast.walk(n)):
                return True
    return False


def is_test(path):
    """A pytest module: defines test functions (a generator may be named test_*.py, e.g. the test-plan writer)."""
    if os.path.basename(path) == 'conftest.py':
        return True
    try:
        tree = ast.parse(open(os.path.join(ROOT, path), errors='ignore').read())
    except SyntaxError:
        return False
    return any(isinstance(n, ast.FunctionDef) and n.name.startswith('test_') for n in tree.body)


def test_every_file_writing_script_is_registered():
    loose = [f for f in TRACKED if f.endswith('.py') and not is_test(f)
             and writes_files(open(os.path.join(ROOT, f), errors='ignore').read())
             and not match(f, RUN_GLOBS) and not match(f, NOT_STAGE_GLOBS)]
    assert not loose, ('scripts that write files but are neither a pipeline stage, run by one (invokes), nor listed in '
                       f'not_stages of regen_manifest.json: {loose}')


def test_files_marked_generated_have_a_registered_generator():
    pat = re.compile(r'Generated by `(?:python3 -m )?([\w./-]+)')
    bad = []
    for f in TRACKED:
        if f.endswith('.py') or not os.path.isfile(os.path.join(ROOT, f)):
            continue
        try:
            head = open(os.path.join(ROOT, f), encoding='utf-8').read(20000)
        except (UnicodeDecodeError, OSError):
            continue
        for gen in set(pat.findall(head)):
            gen = gen if gen.endswith(('.py', '.sh')) else gen.replace('.', '/') + '.py'
            if not os.path.isfile(os.path.join(ROOT, gen)):
                bad.append(f'{f}: names {gen}, which does not exist')
            elif match(gen, NOT_STAGE_GLOBS) and not match(gen, RUN_GLOBS):
                continue   # e.g. a one-time migration's frozen page, classified in _rev_stamp
            elif not match(gen, RUN_GLOBS):
                bad.append(f'{f}: generator {gen} is not a pipeline stage')
            elif not match(f, OWNED_GLOBS):
                bad.append(f'{f}: no stage lists it in outputs or amends')
    assert not bad, bad


def test_linguist_generated_files_are_owned_by_a_stage():
    pats = [ln.split()[0] for ln in open(os.path.join(ROOT, '.gitattributes'))
            if 'linguist-generated' in ln and not ln.startswith('#')]
    globs = [p[:-3] + '*' if p.endswith('/**') else p for p in pats]
    loose = [f for f in TRACKED if match(f, globs) and not match(f, OWNED_GLOBS)]
    assert not loose, f'linguist-generated files no stage writes: {loose}'


def test_every_registered_glob_matches_tracked_files():
    empty = [g for g in OWNED_GLOBS + RUN_GLOBS + NOT_STAGE_GLOBS if not any(fnmatch.fnmatch(f, g) for f in TRACKED)]
    assert not empty, f'manifest globs that match no tracked file (stale entries): {empty}'


def test_not_stages_entries_explain_themselves():
    for n in MANIFEST.get('not_stages', []):
        assert n.get('role') and n.get('reason') and n.get('scripts'), n
